        s = left + right
        out = output_grid[r][c]
        if s not in sum_to_output:
            sum_to_output[s] = {}
        sum_to_output[s][out] = sum_to_output[s].get(out, 0) + 1

print("Sum to output mapping:")
for s in sorted(sum_to_output.keys()):
    c2 = sum_to_output[s].get(0, 0)  # count of output=2 (sum==0 for output=2)
