    if c2 == 0 and c3 > 0:
        print(f"Sum {s}: Always 3 ({c3} cases)")
    elif c3 == 0 and c2 > 0:
        print(f"Sum {s}: Always 2 ({c2} cases)")
    elif c2 > 0 and c3 > 0:
        print(f"Sum {s}: Mixed ({c2}x 2, {c3}x 3)")
    else:
        print(f"Sum {s}: Total {c2+c3} cases")

# Now let me check what SINGLE sums can determine output completely
always_3_sums = [s for s in sum_to_output if sum_to_output[s] == {1: c3} and c3 > 0]
