# Verify the pattern: output[r][c] = 2 if input[r][c] in [0,5,8] else 3

def predict_output(row, col):
    if input_grid[row][col] in [0, 5, 8]:
        return 2
    else:
        return 3

correct = 0
wrong = 0
mismatches = []

for r in range(15):
    for c in range(13):
        predicted = predict_output(r, c)
        actual = output_grid[r][c]
        if predicted == actual:
            correct += 1
        else:
            wrong += 1
            mismatches.append((r, c, predicted, actual, input_grid[r][c]))

print(f"Correct: {correct}, Wrong: {wrong}")
print(f"\nMismatches (first 10):")
for m in mismatches[:10]:
    print(f"  Row {m[0]}, Col {m[1]}: predicted={m[2]}, actual={m[3]}, input={m[4]}")

# Check: maybe output[r][c] = 2 if input[r][2c+1] (the RIGHT cell) is special?

def predict_output_right_special(row, col):
    right = input_grid[row][2*col+1]
    if right in [0, 5, 8]:
        return 2
    else:
        return 3

correct = 0
wrong = 0

for r in range(15):
    for c in range(13):
        predicted = predict_output_right_special(r, c)
        actual = output_grid[r][c]
        if predicted == actual:
            correct += 1
        else:
            wrong += 1

print(f"Right special hypothesis: Correct={correct}, Wrong={wrong}")

# Also try: output[r][c] = 2 if input[r][2c] (the LEFT cell) OR input[r][2c+1] is special
def predict_output_any_special(row, col):
    left = input_grid[row][2*col]
    right = input_grid[row][2*col+1]
    if left in [0, 5, 8] or right in [0, 5, 8]:
        return 2
    else:
        return 3

correct = 0
wrong = 0

for r in range(15):
    for c in range(13):
        predicted = predict_output_any_special(r, c)
        actual = output_grid[r][c]
        if predicted == actual:
            correct += 1
        else:
            wrong += 1

print(f"Any special hypothesis: Correct={correct}, Wrong={wrong}")

# Check which rows need BOTH cells to be non-2 and non-special to get output=2
